#include "clipboard_transfer.h"

#include <algorithm>
#include <array>
#include <cerrno>
#include <chrono>
#include <cstddef>
#include <fcntl.h>
#include <signal.h>
#include <string>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>
#include <utility>

namespace nk::detail {
namespace {

// Pipes have no MSG_NOSIGNAL. Block SIGPIPE only on this thread and consume
// only the signal generated by this write, preserving an already pending one.
ssize_t write_pipe(int fd, const char* data, std::size_t size) {
    sigset_t blocked;
    sigemptyset(&blocked);
    sigaddset(&blocked, SIGPIPE);
    sigset_t previous;
    if (pthread_sigmask(SIG_BLOCK, &blocked, &previous) != 0) {
        errno = EIO;
        return -1;
    }
    sigset_t pending;
    sigpending(&pending);
    const bool already_pending = sigismember(&pending, SIGPIPE) == 1;
    const auto result = write(fd, data, size);
    const int saved_errno = errno;
    if (result < 0 && saved_errno == EPIPE && !already_pending) {
        const timespec no_wait{};
        while (sigtimedwait(&blocked, nullptr, &no_wait) < 0 && errno == EINTR) {}
    }
    pthread_sigmask(SIG_SETMASK, &previous, nullptr);
    errno = saved_errno;
    return result;
}

} // namespace

ClipboardTransfer::ClipboardTransfer(int fd,
                                     Direction direction,
                                     std::string text,
                                     std::size_t max_bytes,
                                     std::chrono::milliseconds timeout)
    : fd_(fd)
    , direction_(direction)
    , text_(std::move(text))
    , max_bytes_(max_bytes)
    , deadline_(std::chrono::steady_clock::now() + timeout) {
    const int flags = fd_ < 0 ? -1 : fcntl(fd_, F_GETFL);
    if (flags < 0 || fcntl(fd_, F_SETFL, flags | O_NONBLOCK) < 0 ||
        fcntl(fd_, F_SETFD, FD_CLOEXEC) < 0 || text_.size() > max_bytes_) {
        finish(false);
    }
}

ClipboardTransfer::~ClipboardTransfer() {
    if (fd_ >= 0) {
        close(fd_);
    }
}

void ClipboardTransfer::finish(bool success) {
    finished_ = true;
    succeeded_ = success;
    if (fd_ >= 0) {
        close(fd_);
        fd_ = -1;
    }
    if (!success) {
        text_.clear();
    }
}

bool ClipboardTransfer::poll() {
    if (finished_) {
        return true;
    }
    if (std::chrono::steady_clock::now() >= deadline_) {
        finish(false);
        return true;
    }
    constexpr std::size_t WorkBudget = 64U * 1024U;
    std::array<char, 4096> buffer{};
    std::size_t processed = 0;
    while (processed < WorkBudget) {
        if (direction_ == Direction::Write && offset_ == text_.size()) {
            finish(true);
            return true;
        }
        const auto count =
            direction_ == Direction::Read
                ? read(fd_, buffer.data(), std::min(buffer.size(), WorkBudget - processed))
                : write_pipe(fd_,
                             text_.data() + offset_,
                             std::min(WorkBudget - processed, text_.size() - offset_));
        if (count > 0) {
            const auto size = static_cast<std::size_t>(count);
            processed += size;
            if (direction_ == Direction::Read) {
                if (size > max_bytes_ - text_.size()) {
                    finish(false);
                    return true;
                }
                text_.append(buffer.data(), size);
            } else {
                offset_ += size;
            }
        } else if (count < 0 && (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR)) {
            // Yield to the next event-loop turn instead of spinning on signals.
            return false;
        } else {
            finish(count == 0 && direction_ == Direction::Read);
            return true;
        }
    }
    return false;
}

std::string ClipboardTransfer::take_text() {
    return succeeded_ ? std::move(text_) : std::string{};
}

} // namespace nk::detail
